    go_no_go_boundary_status = (
        "metadata_only_pilot_go_no_go_boundary_ready"
        if approval_readiness_response.approval_readiness_status == "metadata_only_pilot_approval_readiness_ready"
        and approval_readiness_response.approval_readiness_decision
        == "approval_readiness_ready_for_human_go_no_go_without_persistence"
        and approval_readiness_response.human_confirmation_required
        and not approval_readiness_response.human_confirmation_captured
        and not approval_readiness_response.decision_record_created
        and not approval_readiness_response.approval_record_created
        and not approval_readiness_response.pilot_start_authorized
        and approval_readiness_response.read_only_status == "read_only_no_state_change"
        and approval_readiness_response.backup_failover_gate_status == "metadata_only_no_state_change"
        and not approval_readiness_response.content_included
        and not approval_readiness_response.persistent_task_created
        and not approval_readiness_response.automation_created
        else "metadata_only_pilot_go_no_go_boundary_blocked"
    )
    go_no_go_boundary_decision = (
        "go_no_go_boundary_ready_without_decision_capture"
        if go_no_go_boundary_status == "metadata_only_pilot_go_no_go_boundary_ready"
        else "go_no_go_boundary_blocked"
    )
    go_no_go_decision_options = _mvp_pilot_go_no_go_decision_options()
    go_no_go_decision_inputs = _mvp_pilot_go_no_go_decision_inputs()
    go_no_go_required_controls = _mvp_pilot_go_no_go_required_controls()
