def build_mvp_pilot_go_no_go_boundary_hash(
    report: ProductCockpitMvpPilotGoNoGoBoundaryResponse,
) -> str:
    return stable_hash(canonical_json(report.model_dump(mode="json", exclude={"evidence_hash"})))


def _mvp_pilot_go_no_go_decision_options() -> tuple[str, ...]:
    return ("go", "no_go", "defer")


def _mvp_pilot_go_no_go_decision_inputs() -> tuple[str, ...]:
    return (
        "readiness_packet_id",
        "workflow_boundary_id",
        "decision_record_schema_id",
        "confirmation_template_id",
        "approval_readiness_evidence_hash",
        "approval_workflow_boundary_evidence_hash",
        "preflight_evidence_hash",
        "decision_record_schema_evidence_hash",
        "pilot_gate_evidence_hash",
    )


def _mvp_pilot_go_no_go_required_controls() -> tuple[str, ...]:
    return (
        "explicit_human_go_no_go",
        "tenant_and_role_gates",
        "immutable_evidence_hashes",
        "decision_record_written_separately",
        "approval_persistence_separately_authorized",
        "pilot_execution_separate_boundary",
    )


def _mvp_pilot_go_no_go_prohibited_actions() -> tuple[str, ...]:
    return (
        "go_no_go_decision_stored",
        "approval_record_created",
        "human_confirmation_captured",
        "decision_record_created",
        "pilot_start_authorized",
        "content_preview_rendered",
        "persistent_task_created",
        "automation_created",
    )


def _mvp_pilot_go_no_go_boundary_summary(
    *,
    approval_readiness_response: ProductCockpitMvpPilotApprovalReadinessResponse,
    go_no_go_boundary_decision: str,
) -> tuple[str, ...]:
    open_gaps = ",".join(approval_readiness_response.open_foundation_gap_ids) or "none"
    return (
        f"go/no-go boundary decision: {go_no_go_boundary_decision}",
        f"approval readiness decision: {approval_readiness_response.approval_readiness_decision}",
        f"workflow boundary decision: {approval_readiness_response.boundary_decision}",
        f"decision record schema: {approval_readiness_response.decision_record_schema_id}",
        f"open foundation gaps: {open_gaps}",
        "go/no-go boundary is read-only and stores no decision, approval, decision record or pilot start",
    )


def _mvp_pilot_go_no_go_boundary_checks(*, go_no_go_boundary_status: str) -> tuple[str, ...]:
    if go_no_go_boundary_status == "metadata_only_pilot_go_no_go_boundary_ready":
        return (
            "verify approval readiness evidence before presenting human go/no-go",
            "require tenant-admin/security-admin explicit human decision outside this endpoint",
            "keep decision record, approval persistence and pilot execution separate",
            "confirm no go/no-go decision has been captured",
        )
    return ("repair blocked go/no-go boundary conditions before decision capture wiring",)


def _mvp_pilot_go_no_go_boundary_blockers(
    approval_readiness_response: ProductCockpitMvpPilotApprovalReadinessResponse,
) -> tuple[str, ...]:
    return (
        "go/no-go decision has not been captured",
        "approval record has not been created",
        "human confirmation has not been captured",
        "decision record has not been created",
        "pilot start authorization is not granted by this boundary",
        f"open foundation gaps: {','.join(approval_readiness_response.open_foundation_gap_ids)}",
    )


def _mvp_pilot_go_no_go_boundary_evidence_chain_summary(
    approval_readiness_response: ProductCockpitMvpPilotApprovalReadinessResponse,
) -> tuple[str, ...]:
    return (
        f"approval readiness hash: {approval_readiness_response.evidence_hash}",
        f"approval boundary hash: {approval_readiness_response.approval_workflow_boundary_evidence_hash}",
        f"preflight hash: {approval_readiness_response.preflight_evidence_hash}",
        f"decision schema hash: {approval_readiness_response.decision_record_schema_evidence_hash}",
        f"pilot gate hash: {approval_readiness_response.pilot_gate_evidence_hash}",
    )


