def build_mvp_pilot_decision_capture_boundary_hash(
    report: ProductCockpitMvpPilotDecisionCaptureBoundaryResponse,
) -> str:
    return stable_hash(canonical_json(report.model_dump(mode="json", exclude={"evidence_hash"})))


def _mvp_pilot_decision_capture_inputs() -> tuple[str, ...]:
    return (
        "go_no_go_decision_record_schema_id",
        "go_no_go_boundary_id",
        "readiness_packet_id",
        "workflow_boundary_id",
        "confirmation_template_id",
        "go_no_go_decision_options",
        "go_no_go_decision_record_required_fields",
        "go_no_go_decision_record_schema_evidence_hash",
        "go_no_go_boundary_evidence_hash",
        "approval_readiness_evidence_hash",
    )


def _mvp_pilot_decision_capture_required_controls() -> tuple[str, ...]:
    return (
        "explicit_human_decision_submit",
        "tenant_and_role_gates",
        "schema_field_validation",
        "immutable_evidence_hash_validation",
        "audit_event_before_persistence",
        "separate_persistence_boundary",
    )


def _mvp_pilot_decision_capture_prohibited_actions() -> tuple[str, ...]:
    return (
        "decision_capture_enabled",
        "go_no_go_decision_stored",
        "go_no_go_decision_captured",
        "go_no_go_decision_record_created",
        "approval_record_created",
        "pilot_start_authorized",
        "content_preview_rendered",
        "persistent_task_created",
        "automation_created",
    )


def _mvp_pilot_decision_capture_boundary_summary(
    *,
    go_no_go_record_schema_response: ProductCockpitMvpPilotGoNoGoDecisionRecordSchemaResponse,
    decision_capture_boundary_decision: str,
) -> tuple[str, ...]:
    open_gaps = ",".join(go_no_go_record_schema_response.open_foundation_gap_ids) or "none"
    return (
        f"decision capture boundary decision: {decision_capture_boundary_decision}",
        f"go/no-go record schema decision: {go_no_go_record_schema_response.go_no_go_record_schema_decision}",
        f"go/no-go boundary decision: {go_no_go_record_schema_response.go_no_go_boundary_decision}",
        f"record schema: {go_no_go_record_schema_response.go_no_go_decision_record_schema_id}",
        f"open foundation gaps: {open_gaps}",
        "decision capture boundary is read-only and captures no decision, approval, decision record or pilot start",
    )


def _mvp_pilot_decision_capture_boundary_checks(*, decision_capture_boundary_status: str) -> tuple[str, ...]:
    if decision_capture_boundary_status == "metadata_only_pilot_decision_capture_boundary_ready":
        return (
            "validate go/no-go decision record schema before capture wiring",
            "require explicit human submit outside this endpoint",
            "compare immutable evidence hashes before decision capture",
            "keep decision storage, approval persistence and pilot execution outside this boundary",
        )
    return ("repair blocked decision capture boundary conditions before decision persistence wiring",)


def _mvp_pilot_decision_capture_boundary_blockers(
    go_no_go_record_schema_response: ProductCockpitMvpPilotGoNoGoDecisionRecordSchemaResponse,
) -> tuple[str, ...]:
    return (
        "decision capture is not enabled",
        "go/no-go decision has not been captured",
        "go/no-go decision has not been stored",
        "go/no-go decision record has not been created",
        "pilot start authorization is not granted by this boundary",
        f"open foundation gaps: {','.join(go_no_go_record_schema_response.open_foundation_gap_ids)}",
    )


def _mvp_pilot_decision_capture_boundary_evidence_chain_summary(
    go_no_go_record_schema_response: ProductCockpitMvpPilotGoNoGoDecisionRecordSchemaResponse,
) -> tuple[str, ...]:
    return (
        f"go/no-go record schema hash: {go_no_go_record_schema_response.evidence_hash}",
        f"go/no-go boundary hash: {go_no_go_record_schema_response.go_no_go_boundary_evidence_hash}",
        f"approval readiness hash: {go_no_go_record_schema_response.approval_readiness_evidence_hash}",
        f"preflight hash: {go_no_go_record_schema_response.preflight_evidence_hash}",
        f"pilot gate hash: {go_no_go_record_schema_response.pilot_gate_evidence_hash}",
    )


