def build_mvp_pilot_decision_capture_payload_validation_request_boundary_hash(
    report: ProductCockpitMvpPilotDecisionCapturePayloadValidationRequestBoundaryResponse,
) -> str:
    return stable_hash(canonical_json(report.model_dump(mode="json", exclude={"evidence_hash"})))


def _mvp_pilot_decision_capture_payload_validation_request_required_headers() -> tuple[str, ...]:
    return (
        "X-Tenant-Id",
        "X-User-Id",
        "X-Role-Ids",
        "X-Readable-Object-Ids",
        "Idempotency-Key",
    )


def _mvp_pilot_decision_capture_payload_validation_request_required_fields() -> tuple[str, ...]:
    return (
        "tenant_id",
        "decision_capture_payload_validation_request_contract_id",
        "decision_capture_payload_validation_dry_run_contract_id",
        "decision_capture_payload_validation_dry_run_evidence_hash",
        "go_no_go_decision",
        "human_confirmation_statement",
        "confirmation_role_ids",
        "idempotency_key",
    )


def _mvp_pilot_decision_capture_payload_validation_request_required_controls() -> tuple[str, ...]:
    return (
        "explicit_post_request_required_later",
        "tenant_context_and_payload_tenant_must_match",
        "role_gate_must_pass_before_validation",
        "evidence_hash_must_match_current_dry_run",
        "idempotency_key_required",
        "request_result_must_not_persist_in_boundary",
    )


def _mvp_pilot_decision_capture_payload_validation_request_rejected_conditions() -> tuple[str, ...]:
    return (
        "request_without_tenant_context",
        "request_with_mismatched_tenant",
        "request_with_stale_dry_run_hash",
        "request_with_missing_idempotency_key",
        "request_attempting_decision_storage",
        "request_attempting_pilot_start",
    )


def _mvp_pilot_decision_capture_payload_validation_request_boundary_summary(
    *,
    payload_validation_dry_run_response: ProductCockpitMvpPilotDecisionCapturePayloadValidationDryRunResponse,
    boundary_decision: str,
) -> tuple[str, ...]:
    open_gaps = ",".join(payload_validation_dry_run_response.open_foundation_gap_ids) or "none"
    dry_run_decision = payload_validation_dry_run_response.decision_capture_payload_validation_dry_run_decision
    return (
        f"payload validation request boundary decision: {boundary_decision}",
        f"payload validation dry-run decision: {dry_run_decision}",
        "request contract: mvp_pilot_decision_capture_payload_validation_request_contract_v1",
        "request boundary is metadata-only and accepts no request payload",
        f"open foundation gaps: {open_gaps}",
        "decision storage, approval persistence and pilot start remain outside this request boundary",
    )


def _mvp_pilot_decision_capture_payload_validation_request_boundary_checks(*, boundary_status: str) -> tuple[str, ...]:
    if boundary_status == "metadata_only_pilot_decision_capture_payload_validation_request_boundary_ready":
        return (
            "publish request boundary without enabling POST handler",
            "require tenant context and idempotency key before future payload validation",
            "require current dry-run evidence hash before future validation",
            "keep validation result and decision storage outside request boundary",
        )
    return ("repair blocked payload validation request boundary conditions before POST wiring",)


def _mvp_pilot_decision_capture_payload_validation_request_boundary_blockers(
    payload_validation_dry_run_response: ProductCockpitMvpPilotDecisionCapturePayloadValidationDryRunResponse,
) -> tuple[str, ...]:
    return (
        "payload validation request endpoint is not enabled",
        "payload validation request has not been received",
        "payload validation request payload is not accepted",
        "go/no-go decision has not been stored",
        "pilot start authorization is not granted by this request boundary",
        f"open foundation gaps: {','.join(payload_validation_dry_run_response.open_foundation_gap_ids)}",
    )


