def _activation_approval_request_execution_result_handler_execution_result_execution_result_execution_dry_run_summary(
    *,
    handler_execution_result_execution_result_execution_skeleton_response: (
        _ActivationApprovalRequestExecutionResultHandlerExecutionResultExecutionResultExecutionSkeletonResponse
    ),
    dry_run_decision: str,
) -> tuple[str, ...]:
    open_gaps = (
        ",".join(handler_execution_result_execution_result_execution_skeleton_response.open_foundation_gap_ids)
        or "none"
    )
    skeleton_payload = handler_execution_result_execution_result_execution_skeleton_response.model_dump()
    skeleton_decision = skeleton_payload[
        "decision_capture_payload_validation_request_execution_activation_approval_request_execution_result_handler_execution_result_execution_result_execution_skeleton_decision"
    ]
    return (
        f"payload validation request execution activation approval request execution result handler execution result execution result execution dry-run decision: {dry_run_decision}",  # noqa: E501
        f"payload validation request execution activation approval request execution result handler execution result execution result execution skeleton decision: {skeleton_decision}",  # noqa: E501
        (
            "approval request execution result handler execution result execution result execution dry-run contract: "
            "mvp_pilot_decision_capture_payload_validation_request_execution_activation_approval_request_execution_result_handler_execution_result_execution_result_execution_dry_run_contract_v1"
        ),
        (
            "approval request execution result handler execution result execution result execution dry-run "
            "profiles future handler result execution but executes and persists nothing"
        ),
        f"open foundation gaps: {open_gaps}",
        (
            "handler registration, handler execution, handler execution result execution, result acceptance, "
            "approval persistence, activation grant and pilot start remain outside this dry-run"
        ),
    )


